settings.custom_css:
/* =========================================================
   RAMIS SHOP
   PREMIUM USER ACCOUNT / MY ACCOUNT
   Brand System
   Primary:   #006660
   Dark:      #003F3C
   Secondary: #004F4B
   Gold:      #FFCE3A
========================================================= */


/* =========================================================
   1. RAMIS DESIGN TOKENS
========================================================= */

.woocommerce {
    --ramis-primary: #006660;
    --ramis-primary-dark: #004F4B;
    --ramis-dark: #003F3C;
    --ramis-secondary: #004F4B;
    --ramis-gold: #FFCE3A;

    --ramis-text: #183C3A;
    --ramis-muted: #7B8786;
    --ramis-light: #F8FAF9;
    --ramis-border: #E9EEEE;
}


/* =========================================================
   2. MAIN ACCOUNT DASHBOARD
========================================================= */

.woocommerce .wc-dashboard {
    width: 100%;

    margin: 0 0 24px !important;
    padding: 0 !important;

    background: #FFFFFF;

    border: 1px solid var(--ramis-border);
    border-radius: 20px;

    overflow: hidden;

    box-shadow:
        0 12px 38px rgba(0, 102, 96, 0.07);
}


/* =========================================================
   3. PREMIUM PROFILE HERO
========================================================= */

.woocommerce .wc-dashboard .store-avatar-header {
    position: relative;
    isolation: isolate;

    display: flex;
    align-items: center;
    justify-content: center;

    min-height: 190px;

    padding: 30px 28px;

    overflow: hidden;

    background:
        radial-gradient(
            circle at 88% 15%,
            rgba(255,206,58,0.12),
            transparent 29%
        ),
        radial-gradient(
            circle at 8% 85%,
            rgba(0,180,165,0.17),
            transparent 34%
        ),
        linear-gradient(
            135deg,
            #003F3C 0%,
            #006660 52%,
            #00332F 100%
        );

    border: 0;

    border-radius: 20px 20px 0 0;

    box-sizing: border-box;

    box-shadow:
        inset 0 -1px 0 rgba(255,255,255,0.08);
}


/* =========================================================
   PROFILE HERO — GOLD ATMOSPHERIC GLOW
========================================================= */

.woocommerce .wc-dashboard .store-avatar-header::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    top: -190px;
    right: 8%;

    background:
        radial-gradient(
            circle,
            rgba(255,206,58,0.16) 0%,
            rgba(255,206,58,0.06) 35%,
            transparent 70%
        );

    border-radius: 50%;

    filter: blur(12px);

    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   PROFILE HERO — GREEN ATMOSPHERIC GLOW
========================================================= */

.woocommerce .wc-dashboard .store-avatar-header::after {
    content: "";

    position: absolute;

    width: 340px;
    height: 340px;

    bottom: -245px;
    left: 3%;

    background:
        radial-gradient(
            circle,
            rgba(0,190,175,0.13) 0%,
            transparent 68%
        );

    border-radius: 50%;

    filter: blur(18px);

    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   4. PROFILE AVATAR
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-header .profile-img {
    position: relative;
    z-index: 2;

    flex: 0 0 auto;

    width: 100px;
    height: 100px;

    margin: 0;

    padding: 4px;

    border-radius: 50%;

    overflow: visible;

    background:
        linear-gradient(
            135deg,
            #FFFFFF 0%,
            rgba(255,255,255,0.92) 52%,
            rgba(255,206,58,0.78) 100%
        );

    border: 0;

    box-shadow:
        0 14px 38px rgba(0,0,0,0.25),
        0 0 0 1px rgba(255,255,255,0.18);

    box-sizing: border-box;

    transition:
        transform .4s cubic-bezier(.2,.8,.2,1),
        box-shadow .4s ease;
}


/* =========================================================
   AVATAR — GOLD OUTER RING
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-header .profile-img::before {
    content: "";

    position: absolute;

    inset: -6px;

    border: 1px solid rgba(255,206,58,0.42);

    border-radius: 50%;

    pointer-events: none;

    z-index: -1;

    transition:
        border-color .4s ease,
        box-shadow .4s ease;
}


/* =========================================================
   AVATAR IMAGE
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-header .profile-img img {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;

    border-radius: 50%;

    border: 0;

    box-shadow:
        inset 0 0 0 1px rgba(0,0,0,0.04);
}


/* =========================================================
   REMOVE POSSIBLE LOADER
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-header .profile-img .loader {
    display: none !important;
}


/* =========================================================
   AVATAR HOVER
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-header:hover .profile-img {
    transform:
        translateY(-4px)
        scale(1.025);

    box-shadow:
        0 18px 45px rgba(0,0,0,0.29),
        0 0 28px rgba(255,206,58,0.10);
}


.woocommerce .wc-dashboard
.store-avatar-header:hover .profile-img::before {
    border-color: rgba(255,206,58,0.62);

    box-shadow:
        0 0 22px rgba(255,206,58,0.12);
}


/* =========================================================
   5. PROFILE FOOTER / USER INFORMATION
========================================================= */

.woocommerce .wc-dashboard .store-avatar-footer {
    position: relative;
    z-index: 3;

    padding: 21px 25px 25px;

    text-align: center;

    background:
        linear-gradient(
            180deg,
            #003F3C 0%,
            #004F4B 100%
        );

    border: 0;

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.06);
}


/* =========================================================
   USER NAME
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-footer .store-name {
    position: relative;

    display: block;

    margin: 0 0 6px !important;

    color: #FFFFFF !important;

    font-size: clamp(19px, 2vw, 23px) !important;

    font-weight: 900 !important;

    line-height: 1.65;

    letter-spacing: -0.2px;

    text-shadow:
        0 3px 15px rgba(0,0,0,0.18);
}


/* =========================================================
   GOLD ACCENT UNDER USER NAME
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-footer .store-name::after {
    content: "";

    display: block;

    width: 48px;
    height: 3px;

    margin: 8px auto 0;

    background: var(--ramis-gold);

    border-radius: 20px;

    box-shadow:
        0 0 12px rgba(255,206,58,0.16);

    transition:
        width .4s cubic-bezier(.2,.8,.2,1),
        box-shadow .4s ease;
}


.woocommerce .wc-dashboard
.store-avatar-footer:hover .store-name::after {
    width: 72px;

    box-shadow:
        0 0 18px rgba(255,206,58,0.25);
}


/* =========================================================
   USER DETAILS
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-footer .details {
    margin: 0 !important;
}


.woocommerce .wc-dashboard
.store-avatar-footer .reg-date {
    display: inline-block;

    color: rgba(255,255,255,0.68);

    font-size: 12px;

    font-weight: 500;

    line-height: 1.8;
}


/* =========================================================
   SMALL GOLD STATUS DOT
========================================================= */

.woocommerce .wc-dashboard
.store-avatar-footer .details::before {
    content: "";

    display: inline-block;

    width: 5px;
    height: 5px;

    margin-left: 7px;

    vertical-align: middle;

    background: var(--ramis-gold);

    border-radius: 50%;

    box-shadow:
        0 0 9px rgba(255,206,58,0.35);
}


/* =========================================================
   6. ACCOUNT NAVIGATION
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation {
    float: right;

    width: 250px;

    margin: 0 !important;
    padding: 0 !important;

    direction: rtl;
}


/* =========================================================
   NAVIGATION LIST
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation ul {
    margin: 0 !important;
    padding: 8px !important;

    list-style: none !important;

    background: #FFFFFF;

    border: 1px solid var(--ramis-border);

    border-radius: 18px;

    box-shadow:
        0 8px 28px rgba(0,102,96,0.045);
}


/* =========================================================
   MENU ITEM
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation li {
    position: relative;

    margin: 2px 0 !important;
    padding: 0 !important;

    list-style: none !important;
}


/* =========================================================
   MENU LINK
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation li a {
    position: relative;

    display: flex !important;
    align-items: center;

    min-height: 46px;

    padding: 0 15px !important;

    color: #596866 !important;

    background: transparent;

    border-radius: 11px;

    font-size: 13px !important;
    font-weight: 600 !important;

    line-height: 1.6;

    text-decoration: none !important;

    transition:
        background .25s ease,
        color .25s ease,
        transform .25s ease;
}


/* =========================================================
   MENU HOVER
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation li a:hover {
    color: var(--ramis-primary) !important;

    background: rgba(0,102,96,0.065);

    transform: translateX(-2px);
}


/* =========================================================
   ACTIVE MENU
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation
li.is-active > a {
    color: #FFFFFF !important;

    background: var(--ramis-primary) !important;

    box-shadow:
        0 6px 16px rgba(0,102,96,0.15);
}


/* =========================================================
   ACTIVE HOVER
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation
li.is-active > a:hover {
    color: #FFFFFF !important;

    background: var(--ramis-primary-dark) !important;

    transform: none;
}


/* =========================================================
   MENU ICONS
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation li a i {
    width: 28px;

    margin-left: 8px;

    color: currentColor;

    font-size: 13px;

    text-align: center;
}


/* =========================================================
   MOBILE MENU TOGGLE
========================================================= */

.woocommerce .woocommerce-MyAccount-navigation
li.responsive-toggle {
    display: none;
}


/* =========================================================
   7. ACCOUNT CONTENT
========================================================= */

.woocommerce .woocommerce-MyAccount-content {
    float: left;

    width: calc(100% - 275px);

    margin: 0 !important;

    padding: 28px !important;

    background: #FFFFFF;

    border: 1px solid var(--ramis-border);

    border-radius: 20px;

    box-sizing: border-box;

    direction: rtl;

    box-shadow:
        0 8px 30px rgba(0,102,96,0.045);
}


/* =========================================================
   CLEAR FLOATS
========================================================= */

.woocommerce .woocommerce-MyAccount-content::after {
    content: "";

    display: table;

    clear: both;
}


/* =========================================================
   8. WELCOME TEXT
========================================================= */

.woocommerce .woocommerce-MyAccount-content > p:first-of-type {
    margin: 0 0 12px !important;

    color: #5F6D6B;

    font-size: 14px;

    line-height: 2;
}


.woocommerce .woocommerce-MyAccount-content > p:first-of-type strong {
    color: var(--ramis-text);

    font-weight: 800;
}


/* =========================================================
   CONTENT LINKS
========================================================= */

.woocommerce .woocommerce-MyAccount-content p a {
    color: var(--ramis-primary) !important;

    font-weight: 700;

    text-decoration: none !important;

    transition: color .2s ease;
}


.woocommerce .woocommerce-MyAccount-content p a:hover {
    color: var(--ramis-primary-dark) !important;
}


/* =========================================================
   CONTENT DESCRIPTION
========================================================= */

.woocommerce .woocommerce-MyAccount-content > p:nth-of-type(2) {
    margin: 0 0 25px !important;

    padding: 15px 17px;

    color: #687573;

    background: var(--ramis-light);

    border: 1px solid #EDF2F1;

    border-radius: 12px;

    font-size: 13px;

    line-height: 2;
}


/* =========================================================
   9. PROFILE INFORMATION CARD
========================================================= */

.pooshe-profile-content {
    position: relative;

    width: 100%;

    margin: 0 !important;

    padding: 22px !important;

    background: #FFFFFF;

    border: 1px solid var(--ramis-border);

    border-radius: 17px;

    box-sizing: border-box;

    direction: rtl;

    box-shadow:
        0 6px 22px rgba(0,102,96,0.045);
}


/* =========================================================
   PROFILE TABLE
========================================================= */

.pooshe-profile-content table {
    width: 100%;

    margin: 0 !important;

    border-collapse: separate !important;

    border-spacing: 10px !important;

    table-layout: fixed;
}


.pooshe-profile-content tbody,
.pooshe-profile-content tr {
    border: 0 !important;
}


.pooshe-profile-content td {
    width: 50%;

    padding: 18px 20px !important;

    background: var(--ramis-light);

    border: 1px solid #EDF2F1 !important;

    border-radius: 13px;

    vertical-align: middle;

    box-sizing: border-box;

    transition:
        background .25s ease,
        border-color .25s ease,
        box-shadow .25s ease,
        transform .25s ease;
}


.pooshe-profile-content td:hover {
    background: #FFFFFF;

    border-color: rgba(0,102,96,0.18) !important;

    box-shadow:
        0 7px 20px rgba(0,102,96,0.07);

    transform: translateY(-2px);
}


/* =========================================================
   INFORMATION TITLE
========================================================= */

.pooshe-profile-content .title {
    position: relative;

    margin-bottom: 6px;

    padding-right: 12px;

    color: #7B8786;

    font-size: 12px;

    font-weight: 500;

    line-height: 1.8;
}


.pooshe-profile-content .title::before {
    content: "";

    position: absolute;

    right: 0;
    top: 50%;

    width: 3px;
    height: 15px;

    background: var(--ramis-primary);

    border-radius: 10px;

    transform: translateY(-50%);
}


/* =========================================================
   INFORMATION VALUE
========================================================= */

.pooshe-profile-content .value {
    color: var(--ramis-text);

    font-size: 14px;

    font-weight: 700;

    line-height: 1.8;

    word-break: break-word;
}


/* =========================================================
   10. EDIT PROFILE BUTTON
========================================================= */

.pooshe-profile-content .pooshe-edit-profile-btn {
    display: inline-flex !important;

    align-items: center;
    justify-content: center;

    gap: 8px;

    margin-top: 14px;

    min-height: 43px;

    padding: 0 20px !important;

    background: var(--ramis-primary) !important;

    color: #FFFFFF !important;

    border: 1px solid var(--ramis-primary) !important;

    border-radius: 10px;

    font-size: 12px !important;

    font-weight: 700 !important;

    text-decoration: none !important;

    box-shadow:
        0 6px 16px rgba(0,102,96,0.13);

    transition:
        background .25s ease,
        transform .25s ease,
        box-shadow .25s ease;
}


.pooshe-profile-content
.pooshe-edit-profile-btn i {
    color: #FFFFFF !important;

    font-size: 13px;

    transition:
        transform .25s ease;
}


.pooshe-profile-content
.pooshe-edit-profile-btn:hover {
    background: var(--ramis-primary-dark) !important;

    border-color: var(--ramis-primary-dark) !important;

    color: #FFFFFF !important;

    transform: translateY(-2px);

    box-shadow:
        0 9px 22px rgba(0,102,96,0.18);
}


.pooshe-profile-content
.pooshe-edit-profile-btn:hover i {
    transform: translateX(-3px);
}


/* =========================================================
   11. TABLET
========================================================= */

@media (max-width: 1024px) {

    .woocommerce .woocommerce-MyAccount-navigation {
        width: 215px;
    }


    .woocommerce .woocommerce-MyAccount-content {
        width: calc(100% - 235px);

        padding: 22px !important;
    }


    .woocommerce .woocommerce-MyAccount-navigation li a {
        min-height: 43px;

        padding: 0 12px !important;

        font-size: 12px !important;
    }


    /* Profile Hero */

    .woocommerce .wc-dashboard
    .store-avatar-header {
        min-height: 165px;

        padding: 25px 22px;

        border-radius: 18px 18px 0 0;
    }


    .woocommerce .wc-dashboard
    .store-avatar-header .profile-img {
        width: 88px;
        height: 88px;
    }


    .woocommerce .wc-dashboard
    .store-avatar-footer {
        padding: 18px 22px 21px;
    }


    .woocommerce .wc-dashboard
    .store-avatar-footer .store-name {
        font-size: 20px !important;
    }


    .pooshe-profile-content {
        padding: 18px !important;
    }


    .pooshe-profile-content td {
        padding: 16px !important;
    }
}


/* =========================================================
   12. MOBILE
========================================================= */

@media (max-width: 767px) {

    /* ---------------------------------------------
       FLOAT RESET
    --------------------------------------------- */

    .woocommerce .woocommerce-MyAccount-navigation,
    .woocommerce .woocommerce-MyAccount-content {
        float: none !important;

        width: 100% !important;
    }


    /* ---------------------------------------------
       DASHBOARD
    --------------------------------------------- */

    .woocommerce .wc-dashboard {
        margin-bottom: 15px !important;

        border-radius: 16px;
    }


    /* ---------------------------------------------
       MOBILE PROFILE HERO
    --------------------------------------------- */

    .woocommerce .wc-dashboard
    .store-avatar-header {
        min-height: 145px;

        padding: 24px 18px;

        border-radius: 16px 16px 0 0;
    }


    .woocommerce .wc-dashboard
    .store-avatar-header::before {
        width: 210px;
        height: 210px;

        top: -135px;
        right: -45px;

        filter: blur(9px);
    }


    .woocommerce .wc-dashboard
    .store-avatar-header::after {
        width: 230px;
        height: 230px;

        bottom: -165px;
        left: -75px;

        filter: blur(15px);
    }


    /* ---------------------------------------------
       MOBILE AVATAR
    --------------------------------------------- */

    .woocommerce .wc-dashboard
    .store-avatar-header .profile-img {
        width: 78px;
        height: 78px;

        padding: 3px;

        box-shadow:
            0 11px 29px rgba(0,0,0,0.23);
    }


    .woocommerce .wc-dashboard
    .store-avatar-header .profile-img::before {
        inset: -5px;
    }


    /* ---------------------------------------------
       MOBILE USER INFO
    --------------------------------------------- */

    .woocommerce .wc-dashboard
    .store-avatar-footer {
        padding: 16px 17px 19px;
    }


    .woocommerce .wc-dashboard
    .store-avatar-footer .store-name {
        font-size: 18px !important;

        line-height: 1.6;
    }


    .woocommerce .wc-dashboard
    .store-avatar-footer .store-name::after {
        width: 44px;

        height: 3px;

        margin-top: 7px;
    }


    .woocommerce .wc-dashboard
    .store-avatar-footer .reg-date {
        font-size: 11px;

        line-height: 1.8;
    }


    /* =====================================================
       MOBILE NAVIGATION
    ===================================================== */

    .woocommerce .woocommerce-MyAccount-navigation {
        margin-bottom: 15px !important;
    }


    .woocommerce .woocommerce-MyAccount-navigation ul {
        padding: 7px !important;

        border-radius: 15px;
    }


    .woocommerce .woocommerce-MyAccount-navigation
    li.responsive-toggle {
        display: block !important;
    }


    .woocommerce .woocommerce-MyAccount-navigation
    li.responsive-toggle a {
        justify-content: center;

        min-height: 43px;

        color: var(--ramis-primary) !important;

        background: rgba(0,102,96,0.07);

        font-weight: 700 !important;
    }


    .woocommerce .woocommerce-MyAccount-navigation
    li:not(.responsive-toggle) a {
        min-height: 42px;

        padding: 0 13px !important;

        font-size: 12px !important;
    }


    /* =====================================================
       MOBILE CONTENT
    ===================================================== */

    .woocommerce .woocommerce-MyAccount-content {
        padding: 17px !important;

        border-radius: 16px;
    }


    .woocommerce .woocommerce-MyAccount-content
    > p:first-of-type {
        font-size: 12px;

        line-height: 2;
    }


    .woocommerce .woocommerce-MyAccount-content
    > p:nth-of-type(2) {
        padding: 12px 14px;

        margin-bottom: 17px !important;

        font-size: 11px;

        line-height: 2;
    }


    /* =====================================================
       MOBILE PROFILE CARD
    ===================================================== */

    .pooshe-profile-content {
        padding: 12px !important;

        border-radius: 14px;
    }


    .pooshe-profile-content table {
        border-spacing: 0 !important;
    }


    .pooshe-profile-content tr {
        display: flex;

        flex-direction: column;

        gap: 8px;

        margin: 0 0 8px !important;
    }


    .pooshe-profile-content td {
        width: 100% !important;

        padding: 14px 15px !important;

        border-radius: 11px;
    }


    .pooshe-profile-content .title {
        margin-bottom: 4px;

        font-size: 11px;
    }


    .pooshe-profile-content .value {
        font-size: 13px;
    }


    .pooshe-profile-content
    .pooshe-edit-profile-btn {
        width: 100%;

        min-height: 42px;

        margin-top: 8px;

        font-size: 12px !important;
    }
}


/* =========================================================
   13. SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

    .woocommerce .woocommerce-MyAccount-content {
        padding: 13px !important;
    }


    .woocommerce .wc-dashboard
    .store-avatar-header {
        min-height: 125px;

        padding: 20px 15px;

        border-radius: 14px 14px 0 0;
    }


    .woocommerce .wc-dashboard
    .store-avatar-header .profile-img {
        width: 68px;
        height: 68px;
    }


    .woocommerce .wc-dashboard
    .store-avatar-footer {
        padding: 14px 14px 17px;
    }


    .woocommerce .wc-dashboard
    .store-avatar-footer .store-name {
        font-size: 16px !important;
    }


    .woocommerce .wc-dashboard
    .store-avatar-footer .reg-date {
        font-size: 10.5px;
    }


    .woocommerce .woocommerce-MyAccount-navigation li a {
        font-size: 11px !important;
    }


    .pooshe-profile-content {
        padding: 10px !important;
    }


    .pooshe-profile-content td {
        padding: 13px !important;
    }


    .pooshe-profile-content .value {
        font-size: 12px;
    }
}


/* =========================================================
   14. REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .woocommerce .wc-dashboard
    .store-avatar-header .profile-img,

    .woocommerce .wc-dashboard
    .store-avatar-footer .store-name::after,

    .pooshe-profile-content td,

    .pooshe-profile-content
    .pooshe-edit-profile-btn,

    .woocommerce .woocommerce-MyAccount-navigation li a {
        transition: none !important;
